method add(lst: seq<int>) returns (sum: int)
    requires |lst| > 0 // The list must be non-empty
    ensures sum == SumEvenAtOddIndices(lst) // The sum of even elements at odd indices
{
    var total := 0;
    var i := 1; // Start from the first odd index

    while i < |lst|
        invariant 0 <= i <= |lst| // Index i is within bounds
        invariant total == SumEvenAtOddIndices(Slice(lst, 0, i)) // Total is the sum of even elements at odd indices up to i
    {
        if lst[i] % 2 == 0 {
            total := total + lst[i]; // Add to total if the element is even
        }
        i := i + 2; // Move to the next odd index
    }

    return total; // Return the computed total
}

